args.command:
cd /root/nanobot-src && python3 -c "
import py_compile, sys, os, pathlib

errors = []
root = pathlib.Path('nanobot')
for f in sorted(root.rglob('*.py')):
    try:
        py_compile.compile(str(f), doraise=True)
    except py_compile.PyCompileError as e:
        errors.append(str(e))

if errors:
    print(f'FAIL: {len(errors)} syntax errors')
    for e in errors:
        print(e)
else:
    print('OK: all .py files compile clean')
" 2>&1
